SELECT o.id::text AS "id", o.order_no AS "orderNo", o.status, o.pay_type AS "payType", o.total_qty AS "totalQty", o.total_amount AS "totalAmount", o.sales_order_id::text AS "salesOrderId", o.out_trade_no AS "outTradeNo", o.paid_at AS "paidAt", o.shipped_at AS "shippedAt", o.created_at AS "createdAt", (SELECT count(*) FROM mall_order_item i WHERE i.order_id = o.id) AS "itemCount", (SELECT string_agg(i.product_name, '、') FROM mall_order_item i WHERE i.order_id = o.id) AS "summary" FROM mall_order o
o.member_id = #{memberId}::uuid
AND o.status = #{status}
ORDER BY o.created_at DESC LIMIT #{limit} OFFSET #{offset}

SELECT count(*) FROM mall_order o

    o.member_id = #{memberId}::uuid

        AND o.status = #{status}
